  return until(page, async () => (await r.getByTestId('claim-form-amount').inputValue().catch(() => '')) === amount
    && !(await c.getByTestId('claim-error').isVisible().catch(() => false)),
    c.getByTestId('claim-error'), 'open claim editor');
}

